    "453=2|448=33518509|447=D|452=11|448=DOR2|447=D|452=1|"
    "55=USD/JPY|460=4|167=FXSWAP|15=USD|"
    "555=2|"
    "600=USD/JPY|1788=1|607=4|556=USD|685=1000000|2346=0|"
